<?php
declare(strict_types=1);
function buildProgressCases(array &$tests,ControlCenter\Application $app,ControlCenter\Config $config,array $owner,array $other):void {
    $sha=str_repeat('a',40);$tenant=null;$brand=null;$id=null;$context=null;
    $c=new ControlCenter\Config($config->root,array_replace($config->values,['brand_builder'=>['enabled'=>true,'publication_enabled'=>true,'channels'=>['testing'],'sources'=>['2.0.115'=>$sha]],'brand_downloads'=>['enabled'=>false]]));$secrets=new ControlCenter\Secrets($c);$artifacts=new ControlCenter\BrandArtifacts($app->db,$secrets,$c);$builder=new ControlCenter\BrandBuilder($app->db,$c,$app->appBrands,$artifacts,$secrets,$app->auth);$progress=new ControlCenter\BrandBuildProgress($app->db,$c);
    $tests['build progress is stage-based source-leased and private with a measured queue-time baseline']=function()use($app,$owner,$other,$builder,$progress,$sha,$c,&$tenant,&$brand,&$id,&$context):void {
        $tenant=$app->management->createReseller($owner,['company'=>'TEST build progress','name'=>'TEST progress operator','email'=>'build-progress@example.test','password'=>'Synthetic-Progress-Password-42!']);$app->db->query('INSERT INTO panel_resellers (panel_id,tenant_id,username,linked_by) VALUES (?,?,?,?)',['89000001',$tenant['id'],'SYNTHETIC-progress',$owner['id']]);
        $asset=$app->appBrands->upload($owner,['tenant_id'=>$tenant['id'],'image'=>'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jSuoAAAAASUVORK5CYII=']);$brand=$app->appBrands->save($owner,['tenant_id'=>$tenant['id'],'name'=>'TEST Progress TV','loading_asset'=>$asset['id'],'logo_asset'=>$asset['id'],'icon_asset'=>$asset['id']]);$id=$app->appBrands->requestBuild($owner,['tenant_id'=>$tenant['id'],'expected_version'=>1])['id'];
        $job=$app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]);$view=$progress->view($job);same('queued',$view['phase']);same(true,$view['indeterminate']);same(null,$view['eta']);same(650,$view['typical']['lower_seconds']);same(1148,$view['typical']['upper_seconds']);
        $context=$builder->claim(['build_id'=>$id,'channel'=>'testing','source_sha'=>$sha,'runner_run_id'=>'5678']);same(1,$context['progress_protocol']);$lease=['build_id'=>$id,'lease_token'=>$context['lease_token']];$builder->heartbeat($lease+['phase'=>'preparing']);$app->db->query('UPDATE app_brand_builds SET progress_started_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 5 SECOND) WHERE id=?',[$id]);$builder->heartbeat($lease+['phase'=>'building']);
        $job=$app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]);same('building',$job['progress_phase']);check(json_decode($job['progress_times'],true)['preparing']>=5);$start=$job['progress_started_at'];$builder->heartbeat($lease+['phase'=>'building']);same($start,$app->db->one('SELECT progress_started_at FROM app_brand_builds WHERE id=?',[$id])['progress_started_at']);
        problem(409,fn()=> $builder->heartbeat($lease+['phase'=>'preparing']));problem(409,fn()=> $builder->heartbeat($lease+['phase'=>'publishing']));problem(422,fn()=> $builder->heartbeat($lease+['phase'=>'complete']));problem(409,fn()=> $builder->heartbeat(['build_id'=>$id,'lease_token'=>str_repeat('0',64),'phase'=>'retaining']));
        $public=$app->appBrands->get($owner,['tenant_id'=>$tenant['id']])['builds'][0];check(isset($public['progress']));$json=json_encode($public,JSON_THROW_ON_ERROR);check(!str_contains($json,$context['lease_token']));check(!isset($public['lease_hash'],$public['runner_run_id'],$public['progress_times'],$public['manifest']));problem(404,fn()=> $app->appBrands->get($other,['tenant_id'=>$tenant['id']]));
        $view=$progress->view($app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]));same(1,$view['completed_stages']);same('measured_baseline',$view['eta']['source']);
        $app->db->query('UPDATE app_brand_builds SET progress_updated_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 200 SECOND) WHERE id=?',[$id]);$view=$progress->view($app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]));same(true,$view['stale']);same(null,$view['eta']);
        $builder->heartbeat($lease);$app->db->query('UPDATE app_brand_builds SET build_started_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2000 SECOND) WHERE id=?',[$id]);$view=$progress->view($app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]));same(true,$view['eta']['overdue']);same(1,$view['completed_stages']);
    };
    $tests['expired attempts stop ETA and reset telemetry without letting an old lease change the retry']=function()use($app,$builder,$progress,$sha,&$id,&$context):void {
        $old=$context;$app->db->query('UPDATE app_brand_builds SET lease_until=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE id=?',[$id]);$builder->maintain();$view=$progress->view($app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]));same('failed',$view['phase']);same(true,$view['paused']);same(null,$view['eta']);
        $context=$builder->claim(['build_id'=>$id,'channel'=>'testing','source_sha'=>$sha,'runner_run_id'=>'5678']);$job=$app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]);same(2,(int)$job['build_attempt']);same(null,$job['progress_phase']);same([],json_decode($job['progress_times'],true));same(true,$progress->view($job)['indeterminate']);
        problem(409,fn()=> $builder->heartbeat(['build_id'=>$id,'lease_token'=>$old['lease_token'],'phase'=>'verifying']));$builder->heartbeat(['build_id'=>$id,'lease_token'=>$context['lease_token'],'phase'=>'building']);
    };
    $tests['ETA learns successful active-stage timings and only verified publication reaches complete']=function()use($app,$owner,$builder,$progress,&$id,&$context,&$tenant,&$brand):void {
        $job=$app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]);
        foreach([300,360,420] as $n){$fake=ControlCenter\Database::id();$times=['preparing'=>10,'building'=>$n,'verifying'=>20,'retaining'=>20,'publishing'=>20,'mirroring'=>10];$app->db->query("INSERT INTO app_brand_builds (id,brand_id,brand_version,app_version,manifest,requested_by,state,build_channel,progress_times,created_at,published_at) VALUES (?,?,?,?,?,?,'published','testing',?,DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 3 DAY),DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY))",[$fake,$brand['id'],$n,'0.0.'.$n,$job['manifest'],$owner['id'],json_encode($times,JSON_THROW_ON_ERROR)]);}
        $app->db->query('UPDATE app_brand_builds SET progress_started_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 15 SECOND) WHERE id=?',[$id]);$view=$progress->view($app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]));same('measured_builds',$view['eta']['source']);same(3,$view['eta']['samples']);check($view['eta']['lower_seconds']>=350&&$view['eta']['lower_seconds']<=355);check($view['eta']['upper_seconds']>=470&&$view['eta']['upper_seconds']<=475);
        $lease=['build_id'=>$id,'lease_token'=>$context['lease_token']];$builder->heartbeat($lease+['phase'=>'verifying']);$builder->heartbeat($lease+['phase'=>'retaining']);$receipt=$context['expected'];unset($receipt['release_tag'],$receipt['asset_name']);$receipt+=['source_sha'=>$context['source_sha'],'apk_sha256'=>str_repeat('d',64),'apk_size_bytes'=>150000000,'provenance_sha256'=>str_repeat('e',64)];$builder->prepared($lease+['receipt'=>$receipt]);
        $view=$progress->view($app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]));same('prepared',$view['phase']);same(4,$view['completed_stages']);same(true,$view['paused']);same(null,$view['eta']);
        $builder->authorize($lease+['confirmed_publication'=>true]);$builder->heartbeat($lease+['phase'=>'mirroring']);$view=$progress->view($app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]));same(5,$view['completed_stages']);check($view['completed_stages']<$view['total_stages']);
        $builder->finish($lease+['receipt'=>$receipt]);$view=$progress->view($app->db->one('SELECT * FROM app_brand_builds WHERE id=?',[$id]));same('complete',$view['phase']);same(6,$view['completed_stages']);same(null,$view['eta']);problem(409,fn()=> $builder->heartbeat($lease+['phase'=>'building']));
        same($brand['package_name'],$app->appBrands->get($owner,['tenant_id'=>$tenant['id']])['brand']['package_name']);
    };
}
